<body>
  <header>
    <div style="display:flex;align-items:center;gap:.6rem">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:800">Holistic Medicine</div>
        <div style="font-size:.85rem;color:var(--muted)">A practical, whole-life view</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="approach.html">Our Way</a>
      <a href="pricing.html">Pricing</a>
