      <a href="contact.html" style="margin-left:1rem">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="reveal" data-reveal>
        <h1>We translate your daily pattern into practical steps</h1>
        <p class="muted">We start by listening: what matters, what’s getting in the way, and what tiny changes you can carry forward. Our work is educational and collaborative, not prescriptive.</p>
        <p class="quote">"Small adjustments that align with your life are more likely to stick."</p>
      </div>
      <div style="margin-left:auto;display:flex;flex-direction:column;gap:.6rem">
        <button id="tryBtn2" style="border:1px solid var(--accent);background:transparent;padding:.55rem .8rem;border-radius:9px;color:var(--accent);font-weight:700">Try a guided practice</button>
        <a href="book.html" style="background:var(--accent);color:white;padding:.55rem .8rem;border-radius:9px;text-decoration:none;font-weight:700;display:inline-block;text-align:center">Schedule a conversation</a>
      </div>
    </section>

    <section style="margin-top:1.2rem" class="reveal" data-reveal>
