        entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); io.unobserve(en.target); } });
      },{threshold:0.12});
      nodes.forEach(n=>io.observe(n));
    })();

    // Simple modal: smaller experience of the guided exercise (non-interactive text)
    (function(){
      const backdrop = document.getElementById('modalBackdrop2');
      const tryBtn = document.getElementById('tryBtn2');
      const closeBtn = document.getElementById('close2');
      const content = document.getElementById('modalContent2');
      tryBtn.addEventListener('click', ()=>{
        backdrop.style.display='flex'; backdrop.setAttribute('aria-hidden','false');
        content.innerHTML = '<ol><li><strong>Breathe:</strong> three slow breaths.</li><li><strong>Notice:</strong> one small relief in your day.</li><li><strong>Plan:</strong> one tiny next step to repeat tomorrow.</li></ol>';
      });
      closeBtn.addEventListener('click', ()=>{ backdrop.style.display='none'; backdrop.setAttribute('aria-hidden','true'); });
      backdrop.addEventListener('click', (e)=>{ if(e.target===backdrop){ backdrop.style.display='none'; backdrop.setAttribute('aria-hidden','true'); }});
      document.addEventListener('keydown',(e)=>{ if(e.key==='Escape') backdrop.style.display='none'; });
    })();
  </script>
</body>
